}
.lc-luke-oben  { top: 0;    transform-origin: 50% 0;    --hin: -100%; }
.lc-luke-unten { bottom: 0; transform-origin: 50% 100%; --hin:  100%; }
/* Auf — kurz offen — wieder zu. Genau das, was er beschrieben hat. */
@keyframes lcLukeAuf {
  0%   { transform: translateY(var(--hin)); }
  18%  { transform: translateY(0); }
  30%  { transform: translateY(0); }
  46%  { transform: translateY(calc(var(--hin) * .92)); }
  74%  { transform: translateY(calc(var(--hin) * .92)); }
