  background: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20100%20100%22%3E%3Cdefs%3E%3Cg%20id%3D%22ef%22%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%280%29%22%2F%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%2860%29%22%2F%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%28120%29%22%2F%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%28180%29%22%2F%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%28240%29%22%2F%3E%3Cpath%20d%3D%22M0%2C0%20L0%2C-10.0%20M0%2C-3.4%20L2.3%2C-4.8%20M0%2C-3.4%20L-2.3%2C-4.8%20M0%2C-5.4%20L1.9%2C-6.6%20M0%2C-5.4%20L-1.9%2C-6.6%20M0%2C-7.2%20L1.5%2C-8.1%20M0%2C-7.2%20L-1.5%2C-8.1%20M0%2C-8.7%20L1.1%2C-9.4%20M0%2C-8.7%20L-1.1%2C-9.4%22%20transform%3D%22rotate%28300%29%22%2F%3E%3C%2Fg%3E%3C%2Fdefs%3E%3Cg%20fill%3D%22none%22%20stroke%3D%22%231d4c6b%22%2